import React from 'react';

import { useNavigate } from 'react-router-dom';

import CommentsWidget from '@apps/Comments/components/CommentsWidget';
import HikingBadge from '@apps/Hiking/@components/HikingBadge';
import Page from '@components/Page';
import PageHeader from '@components/PageHeader';
import { dateRangeToLocaleString } from '@helpers/dateHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';
import PohLoader from '@ui-kit/Loader';

import WorkoutAbout from './WorkoutAbout';
import WorkoutCharts from './WorkoutCharts';
import WorkoutInvites from './WorkoutInvites';
import WorkoutStat from './WorkoutStat';
import WorkoutTags from './WorkoutTags';
import { AuthContext } from '../../../contexts/AuthContext';
import { downloadGpxFromWorkout } from '../../Routes/@helpers/gpx.helper';
import { getOneWorkout } from '../@services/workouts.service';
import { IWorkoutFull } from '../@types/workouts.types';
import WorkoutPhotos from '../components/WorkoutPhotos/WorkoutPhotos';
import WorkoutTypeIcon from '../components/WorkoutTypeIcon';

const Workout: React.FC<{ id: number }> = ({ id }) => {
  const [data, setData] = React.useState<IWorkoutFull | null>(null);
  const [err, setErr] = React.useState<Error>();
  const navigate = useNavigate();
  const authContext = React.useContext(AuthContext);

  React.useEffect(() => {
    const fetchData = async () => {
      const d = await getOneWorkout(id);
      setData(d);
    };

    fetchData().catch(setErr);
  }, [id]);

  if (data == null) {
    return (
      <div style={{ height: '400px' }} className="d-flex align-items-center justify-content-center">
        <PohLoader />
      </div>
    );
  }

  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;

  return (
    <Page
      title={data.name}
      description={data.description}
      keywords={[data.activity_type, data.type.name]}
    >
      <meta property="article:section" content={data.type.name} />
      <meta property="article:published_time" content={data.date_upload?.toISOString()} />
      {data.date_update && (
        <meta property="article:modified_time" content={data.date_update?.toISOString()} />
      )}
      <meta property="article:tag" content={data.type.name} />

      <>
        <Breadcrumb
          data={[
            { href: `/workouts`, text: 'Тренировки' },
            { href: `/workouts/${id}`, text: data.name, active: true },
          ]}
        />
        <PohContainer>
          <PageHeader
            title={
              <div className="d-inline-flex align-items-center">
                <strong className="d-inline-block mt-n1" title={data.type.name}>
                  <WorkoutTypeIcon type={data.type} style={{ width: 36, height: 36 }} />
                </strong>
                &nbsp;
                {data.name}
              </div>
            }
          >
            {authContext.user && +authContext.user?.id === data.user.id && (
              <>
                <PohButton
                  size={ButtonSize.Small}
                  variant={ButtonVariant.Light}
                  onClick={() => navigate(`/workouts/${data.id}/markup`)}
                  className="ms-2"
                >
                  Разметить
                </PohButton>
                <PohButton
                  size={ButtonSize.Small}
                  variant={ButtonVariant.Light}
                  onClick={() => navigate(`/workouts/${data.id}/edit`)}
                  className="ms-2"
                >
                  Редактировать
                </PohButton>
              </>
            )}
            <PohButton
              size={ButtonSize.Small}
              variant={ButtonVariant.Light}
              onClick={() => downloadGpxFromWorkout(data, { name: data.name })}
              className="ms-2  text-nowrap"
            >
              Скачать GPX
            </PohButton>
          </PageHeader>

          <PohRow>
            <PohCol sm={8}>
              <div className="mt-n3">
                <div className="mb-2 d-flex align-items-center justify-content-between">
                  <small className="text-muted d-flex justify-content-between">
                    {dateRangeToLocaleString(data.date_start, data.date_finish)}
                  </small>
                  <WorkoutAbout workout={data} />
                </div>
                {data.description.length > 0 && (
                  <div className="mb-2">
                    <em>{data.description}</em>
                  </div>
                )}
              </div>
              <WorkoutStat data={data} />

              <WorkoutCharts height={380} trackPoints={data.track} />

              <br />

              <details>
                <summary>Комментарии</summary>
                <CommentsWidget id_workout={id} startText="Стать первым комментатором :)" />
              </details>
            </PohCol>
            <PohCol sm={4}>
              {data.hiking?.id && (
                <HikingBadge
                  hiking={data.hiking}
                  className="d-flex align-items-center mx-2 flex-row-reversed text-end"
                  style={{ fontSize: 13, cursor: 'pointer', flexDirection: 'row-reverse' }}
                  onClick={() => navigate(`/hiking/${data.hiking?.id}`)}
                  tabIndex={1}
                />
              )}
              <WorkoutInvites
                id_workout={id}
                canEdit={Boolean(authContext.user?.id == data.trackOwner.id)}
                className="my-2"
              />
              <WorkoutPhotos
                id_workout={id}
                photos={data.photos}
                onChangePhotos={(up) => {
                  setData((cur) => (cur ? { ...cur, photos: up } : null));
                }}
                canEdit={Boolean(authContext.user && +authContext.user?.id === data.user.id)}
                className="mb-2"
              />

              <WorkoutTags
                id_workout={id}
                tags={data.tags}
                onChangeTags={(up) => {
                  setData((cur) => (cur ? { ...cur, tags: up } : null));
                }}
                canEdit={Boolean(authContext.user && +authContext.user?.id === data.user.id)}
              />
            </PohCol>
          </PohRow>
        </PohContainer>
      </>
    </Page>
  );
};

export default Workout;
